<template><div class="print-page"><div class="toolbar no-print"><el-button @click="router.back()">返回</el-button><el-button type="primary" icon="Printer" @click="print">打印</el-button></div><A4Canvas v-if="info" :padding-mm="15"><PrintCompanyHeader variant="center"/><h1>发 票</h1><div class="info"><div>发票号：{{info.invoiceNo}}</div><div>日期：{{info.invoiceDate||'-'}}</div><div>客户：{{info.customerName||'-'}}</div><div>税号：{{info.taxpayerId||'-'}}</div><div>地址：{{info.address||'-'}}</div><div>电话：{{info.phone||'-'}}</div><div>开户行：{{info.bankName||'-'}}</div><div>账号：{{info.bankAccount||'-'}}</div></div><table><thead><tr><th>编码</th><th>名称</th><th>数量</th><th>单价</th><th>金额</th></tr></thead><tbody><tr v-for="(x,i) in items" :key="i"><td>{{x.productCode||'-'}}</td><td>{{x.productName||'-'}}</td><td class="right">{{x.quantity||'-'}}</td><td class="right">{{money(x.unitPrice)}}</td><td class="right">{{money(x.amount)}}</td></tr><tr v-if="!items.length"><td colspan="5" class="center">无关联订单明细</td></tr></tbody></table><div class="amount"><span>金额：{{money(info.invoiceAmount)}}</span><span>税额：{{money(info.taxAmount)}}</span><b>价税合计：{{money(info.totalAmount)}}</b></div><div class="sign">开票人：________________</div></A4Canvas></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import A4Canvas from '@/components/A4Canvas/index.vue';import PrintCompanyHeader from '@/components/PrintCompanyHeader.vue';import{salesInvoiceApi,type SalesInvoice}from'@/api/sales/invoice';import{orderApi}from'@/api/sales/order';const route=useRoute(),router=useRouter(),info=ref<SalesInvoice>(),items=ref<any[]>([]);const money=(v?:number)=>v==null?'-':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2});async function print(){if(!info.value)return;try{await salesInvoiceApi.printLog(info.value.invoiceId);window.print()}catch{ElMessage.error('打印留痕失败，请重试')}}onMounted(async()=>{const r:any=await salesInvoiceApi.detail(Number(route.params.id));info.value=r.data;if(info.value?.orderId){const o:any=await orderApi.getOrder(info.value.orderId);items.value=o.data?.products||o.data?.items||[]}})</script>
<style scoped>.print-page{min-height:100vh;background:#eef0f3;padding:20px}.toolbar{max-width:794px;margin:0 auto 16px;display:flex;justify-content:space-between}h1{text-align:center;letter-spacing:12px;border-bottom:2px solid #2b5aa7;padding-bottom:10px}.info{display:grid;grid-template-columns:1fr 1fr;gap:7px;font-size:11px;margin:14px 0}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #bbb;padding:7px}th{background:#2b5aa7;color:white}.right{text-align:right}.center{text-align:center}.amount{display:flex;justify-content:flex-end;gap:24px;margin-top:16px;font-size:12px}.sign{margin-top:65px;text-align:right;font-size:12px}@media print{.print-page{padding:0;background:white}}</style>
